3	public sealed record ResultadoIdentidades(bool Superado, bool SuperacionNueva, IReadOnlyList<string> Ids);
4	
5	public sealed class LimitadorIdentidades
6	{
7	    private const int UmbralDeLimpieza = 10_000;
8	
9	    private readonly Lock _candado = new();
10	    private readonly Dictionary<string, List<(DateTimeOffset Momento, string Id)>> _porIp = [];
11	    private readonly IReloj _reloj;
12	    private readonly LimitesAsistente _limites;
13	
14	    public LimitadorIdentidades(IReloj reloj, LimitesAsistente limites)
15	    {
16	        _reloj = reloj;
17	        _limites = limites;
18	    }
19	
20	    private TimeSpan Ventana => TimeSpan.FromMinutes(_limites.VentanaIdentidadesMinutos);
21	
22	    public ResultadoIdentidades Registrar(string ipOrigen, string usuarioId)
23	    {
24	        lock (_candado)
25	        {
26	            var ahora = _reloj.AhoraUtc;
27	            LimpiarSiHaceFalta(ahora);
28	            var entradas = ObtenerVigentes(ipOrigen, ahora);
29	            var antes = entradas.Select(e => e.Id).Distinct().Count();
30	            entradas.Add((ahora, usuarioId));
31	            var ids = entradas.Select(e => e.Id).Distinct().ToList();
32	            var superado = ids.Count > _limites.MaximoIdentidadesPorIp;
33	            return new ResultadoIdentidades(superado, superado && antes <= _limites.MaximoIdentidadesPorIp, ids);
34	        }
35	    }
36	
37	    private List<(DateTimeOffset Momento, string Id)> ObtenerVigentes(string ipOrigen, DateTimeOffset ahora)
38	    {
39	        if (!_porIp.TryGetValue(ipOrigen, out var entradas))
40	        {
41	            entradas = [];
42	            _porIp[ipOrigen] = entradas;
43	        }
44	
45	        entradas.RemoveAll(e => ahora - e.Momento > Ventana);
46	        return entradas;
47	    }
48	
49	    private void LimpiarSiHaceFalta(DateTimeOffset ahora)
50	    {
51	        if (_porIp.Count < UmbralDeLimpieza)
52	        {
53	            return;
54	        }
55	
56	        foreach (var ip in _porIp.Keys.ToList())
57	        {
58	            _porIp[ip].RemoveAll(e => ahora - e.Momento > Ventana);
59	            if (_porIp[ip].Count == 0)
60	            {
61	                _porIp.Remove(ip);
62	            }
63	        }
64	    }
65	}
