3	namespace TutorFlow.Api;
4	
5	public sealed record ResultadoTasa(bool Permitido, int SegundosParaReintentar);
6	
7	public sealed class LimitadorTasaPorIp
8	{
9	    private const int UmbralDeLimpieza = 10_000;
10	
11	    private readonly ConcurrentDictionary<string, Queue<DateTimeOffset>> _porIp = new();
12	    private readonly int _limite;
13	    private readonly TimeSpan _ventana;
14	    private readonly TimeProvider _tiempo;
15	
16	    public LimitadorTasaPorIp(int limite, TimeSpan ventana, TimeProvider tiempo)
17	    {
18	        _limite = limite;
19	        _ventana = ventana;
20	        _tiempo = tiempo;
21	    }
22	
23	    public ResultadoTasa Intentar(string ip)
24	    {
25	        var ahora = _tiempo.GetUtcNow();
26	        LimpiarSiHaceFalta(ahora);
27	        var cola = _porIp.GetOrAdd(ip, _ => new Queue<DateTimeOffset>());
28	        lock (cola)
29	        {
30	            Purgar(cola, ahora);
31	            if (cola.Count < _limite)
32	            {
33	                cola.Enqueue(ahora);
34	                return new ResultadoTasa(true, 0);
35	            }
36	
37	            return new ResultadoTasa(false, SegundosHastaLiberar(cola.Peek(), ahora));
38	        }
39	    }
40	
41	    private int SegundosHastaLiberar(DateTimeOffset masAntigua, DateTimeOffset ahora) =>
42	        Math.Max(1, (int)Math.Ceiling((masAntigua + _ventana - ahora).TotalSeconds));
43	
44	    private void Purgar(Queue<DateTimeOffset> cola, DateTimeOffset ahora)
45	    {
46	        while (cola.Count > 0 && ahora - cola.Peek() >= _ventana)
47	        {
48	            cola.Dequeue();
49	        }
50	    }
51	
52	    private void LimpiarSiHaceFalta(DateTimeOffset ahora)
53	    {
54	        if (_porIp.Count < UmbralDeLimpieza)
55	        {
56	            return;
57	        }
58	
59	        foreach (var (ip, cola) in _porIp)
60	        {
61	            lock (cola)
62	            {
63	                Purgar(cola, ahora);
64	                if (cola.Count == 0)
65	                {
66	                    _porIp.TryRemove(ip, out _);
67	                }
68	            }
69	        }
70	    }
71	}
